function mouse_move_62bebf4dd4732f46492da0da99c4f98c5a491e4870a150af75db9fa98c873a36931385c04f5b1f9918c37ef12e11b4da6ca87aeb12ce54d2e4abf19b6051e0ce(evt) {
    if (evt.buttons > 0) {
          var root = document.getElementById('62bebf4dd4732f46492da0da99c4f98c5a491e4870a150af75db9fa98c873a36931385c04f5b1f9918c37ef12e11b4da6ca87aeb12ce54d2e4abf19b6051e0ce');
          root.pauseAnimations();
          var new_time = 3 * evt.layerX / evt.target.getBBox().width;
          root.setCurrentTime(new_time);
    }
}
function on_click_62bebf4dd4732f46492da0da99c4f98c5a491e4870a150af75db9fa98c873a36931385c04f5b1f9918c37ef12e11b4da6ca87aeb12ce54d2e4abf19b6051e0ce(evt) {
